CREATE TABLE IF NOT EXISTS "DeliveryPromotionApproval" ("id" UUID NOT NULL,"assessmentId" UUID NOT NULL,"pipelineId" UUID NOT NULL,"actorId" VARCHAR(120) NOT NULL,"action" VARCHAR(32) NOT NULL,"status" VARCHAR(32) NOT NULL,"reason" VARCHAR(1000) NOT NULL,"policyVersion" VARCHAR(80) NOT NULL,"requestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"decidedAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "DeliveryApproval_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "DeliveryApproval_assessmentId_key" ON "DeliveryPromotionApproval"("assessmentId");
CREATE INDEX IF NOT EXISTS "DeliveryApproval_pipelineId_status_idx" ON "DeliveryPromotionApproval"("pipelineId","status");
CREATE INDEX IF NOT EXISTS "DeliveryApproval_expiresAt_status_idx" ON "DeliveryPromotionApproval"("expiresAt","status");
CREATE TABLE IF NOT EXISTS "DeliveryGovernanceEvent" ("id" UUID NOT NULL,"assessmentId" UUID,"pipelineId" UUID,"deliveryRunId" UUID,"actorId" VARCHAR(120) NOT NULL,"action" VARCHAR(80) NOT NULL,"previousState" VARCHAR(64),"resultingState" VARCHAR(64),"reason" VARCHAR(2000) NOT NULL,"policyVersion" VARCHAR(80),"evidenceReferences" JSONB NOT NULL,"correlationId" VARCHAR(160),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DeliveryGovernanceEvent_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "DeliveryGovernanceEvent_assessmentId_createdAt_idx" ON "DeliveryGovernanceEvent"("assessmentId","createdAt");
CREATE INDEX IF NOT EXISTS "DeliveryGovernanceEvent_pipelineId_createdAt_idx" ON "DeliveryGovernanceEvent"("pipelineId","createdAt");
CREATE INDEX IF NOT EXISTS "DeliveryGovernanceEvent_action_createdAt_idx" ON "DeliveryGovernanceEvent"("action","createdAt");
CREATE TABLE IF NOT EXISTS "DeliveryGovernanceJobRun" ("id" UUID NOT NULL,"jobKey" VARCHAR(100) NOT NULL,"idempotencyKey" VARCHAR(200) NOT NULL,"status" VARCHAR(32) NOT NULL,"processed" INTEGER NOT NULL DEFAULT 0,"invalidated" INTEGER NOT NULL DEFAULT 0,"expired" INTEGER NOT NULL DEFAULT 0,"releasedLocks" INTEGER NOT NULL DEFAULT 0,"invalidatedCertifications" INTEGER NOT NULL DEFAULT 0,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),"error" VARCHAR(2000),CONSTRAINT "DeliveryGovernanceJobRun_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "DeliveryGovernanceJobRun_idempotencyKey_key" ON "DeliveryGovernanceJobRun"("idempotencyKey");
CREATE INDEX IF NOT EXISTS "DeliveryGovernanceJobRun_jobKey_startedAt_idx" ON "DeliveryGovernanceJobRun"("jobKey","startedAt");
